package vn.edu.eaut.library.dao;
import vn.edu.eaut.library.model.Notification; import vn.edu.eaut.library.utils.DBConnection;
import java.sql.*; import java.util.*;
public class NotificationDAO {
 public int countUnread(int userId){String s="SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,userId);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}catch(SQLException e){throw new RuntimeException("Lỗi đếm thông báo",e);}}
 public List<Notification> findByUserId(int userId){List<Notification> l=new ArrayList<>();String s="SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,userId);try(ResultSet r=p.executeQuery()){while(r.next())l.add(map(r));}}catch(SQLException e){throw new RuntimeException("Lỗi lấy thông báo",e);}return l;}
 public boolean create(int userId,String title,String message,String type){String s="INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,userId);p.setString(2,title);p.setString(3,message);p.setString(4,type);return p.executeUpdate()>0;}catch(SQLException e){throw new RuntimeException("Lỗi tạo thông báo",e);}}
 public boolean markRead(int id,int userId){String s="UPDATE notifications SET is_read=1 WHERE notification_id=? AND user_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);p.setInt(2,userId);return p.executeUpdate()>0;}catch(SQLException e){throw new RuntimeException("Lỗi đánh dấu thông báo",e);}}
 public boolean markAllRead(int userId){String s="UPDATE notifications SET is_read=1 WHERE user_id=? AND is_read=0";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,userId);return p.executeUpdate()>=0;}catch(SQLException e){throw new RuntimeException("Lỗi đọc thông báo",e);}}
 private Notification map(ResultSet r)throws SQLException{Notification n=new Notification();n.setNotificationId(r.getInt("notification_id"));n.setUserId(r.getInt("user_id"));n.setTitle(r.getString("title"));n.setMessage(r.getString("message"));n.setType(r.getString("type"));n.setRead(r.getBoolean("is_read"));Timestamp t=r.getTimestamp("created_at");if(t!=null)n.setCreatedAt(t.toLocalDateTime());return n;}
}
